    "a11yHtml": "<!-- Accessibility -->\n<section class=\"doc-section\"><h2>Accessibility &amp; Keyboard Interaction</h2><p>Requirements for using this component accessibly.</p><div class=\"spec-wrap\"><table class=\"spec-table\"><thead><tr><th scope=\"col\">Topic</th><th scope=\"col\">Requirement</th></tr></thead><tbody><tr><td>Keyboard</td><td>Native anchor: reachable with Tab and activated with Enter.</td></tr><tr><td>Link text</td><td>Describe the destination. Avoid \"click here\".</td></tr><tr><td>Color</td><td>The underline stays, so links aren't identified by color alone.</td></tr></tbody></table></div></section>"
