    "a11yHtml": "<!-- Accessibility -->\n<section class=\"doc-section\"><h2>Accessibility &amp; Keyboard Interaction</h2><p>Requirements for using this component accessibly.</p><div class=\"spec-wrap\"><table class=\"spec-table\"><thead><tr><th scope=\"col\">Topic</th><th scope=\"col\">Requirement</th></tr></thead><tbody><tr><td>Text alternative</td><td>Images need <code>alt</code>. Initials need <code>role=\"img\"</code> and <code>aria-label</code>.</td></tr><tr><td>Status</td><td>Include status in the accessible name.</td></tr><tr><td>Clickable</td><td>Wrap in a native button or link.</td></tr></tbody></table></div></section>"
